async function authenticate(request,db){
 const cookie=request.headers.get('Cookie')||'';const raw=cookie.match(/(?:^|;\s*)tr_demo=([a-zA-Z0-9-]+)/)?.[1];if(!raw)fail(401,'Inicia sesión para abrir el panel.');
 const s=await stmt(db,'SELECT * FROM demo_sessions WHERE token=? AND expires>?',await digest(raw),Date.now()).first();if(!s)fail(401,'Tu sesión demo terminó. Inicia sesión de nuevo.');return s;
}
async function body(request){if(!(request.headers.get('Content-Type')||'').startsWith('application/json'))fail(415,'Utiliza datos JSON.');const length=Number(request.headers.get('Content-Length')||0);if(length>500000)fail(413,'Carga demasiado grande.');const content=await request.text();if(content.length>500000)fail(413,'Carga demasiado grande.');let b;try{b=JSON.parse(content)}catch{fail(400,'Datos inválidos.')}if(!b||typeof b!=='object'||Array.isArray(b))fail(400,'Datos inválidos.');return b;}
function validate(kind,b){
 const d={id:uid(),created:now()};
 if(kind==='clients'){d.name=text(b.name,120);d.segment=['B2B','B2C'].includes(b.segment)?b.segment:fail(400,'Segmento inválido.');d.email=text(b.email??'',150,false);if(d.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email))fail(400,'Email inválido.');d.phone=text(b.phone??'',40,false);d.discount=integer(b.discount??0,0,30);d.notes=text(b.notes??'',500,false);}
 else if(kind==='leads'){d.title=text(b.title,150);d.clientId=text(b.clientId,80);d.stage=stages.includes(b.stage)?b.stage:fail(400,'Etapa inválida.');d.amount=integer(b.amount??0);d.next=date(b.next??'');d.notes=text(b.notes??'',500,false);}
 else if(kind==='products'){for(const k of ['code','name','brand','category','location'])d[k]=text(b[k],k==='name'?150:80);d.price=integer(b.price,1);d.cost=integer(b.cost);d.tax=integer(b.tax??0,0,30);d.stock=integer(b.stock,0,99999);d.min=integer(b.min??0,0,99999);d.verified=false;}
 else if(kind==='tasks'){d.title=text(b.title,150);d.due=date(b.due??'');d.done=b.done===true;d.notes=text(b.notes??'',500,false);}
 else fail(400,'Tipo de registro inválido.');return d;
}
function date(v){if(v==='')return '';const parsed=typeof v==='string'?new Date(v+'T00:00:00Z'):new Date(NaN);if(typeof v!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(v)||!Number.isFinite(parsed.getTime())||parsed.toISOString().slice(0,10)!==v)fail(400,'Fecha inválida.');return v;}
const successfulLog=(db,s,event,id)=>stmt(db,'INSERT INTO demo_records(workspace,kind,id,data) SELECT ?,?,?,? WHERE changes()=1',s.workspace,'audit',uid(),JSON.stringify({event,record:id,role:s.role,...(s.mode==='store'?{actor:s.actor}:{}),at:now()}));
async function update(db,s,kind,id,version,data,event){integer(version,1);const result=await db.batch([stmt(db,'UPDATE demo_records SET data=?,version=version+1 WHERE workspace=? AND kind=? AND id=? AND version=?',JSON.stringify(data),s.workspace,kind,id,version),successfulLog(db,s,event,id)]);if(result[0].meta.changes!==1)fail(409,'El registro cambió. Actualiza el panel antes de guardar.');return {...data,version:version+1};}
async function quote(db,s,b){
 requirePermission(s,'quote.write');await limit(db,s,'documents');const client=await find(db,s,'clients',b.clientId);let member=false;if(s.mode==='store'&&s.customerDatabase&&client.email){await customerSetup(s.customerDatabase);member=!!await stmt(s.customerDatabase,'SELECT id FROM tr_customers WHERE email=?',client.email.trim().toLowerCase()).first();}const discountRate=member?Math.max(20,client.discount):client.discount;
 if(!Array.isArray(b.items)||!b.items.length||b.items.length>30)fail(400,'Añade entre 1 y 30 líneas.');const seen=new Set(),items=[];
 for(const item of b.items){const id=text(item.productId,80);if(seen.has(id))fail(400,'Repite la cantidad, no la misma pieza.');seen.add(id);const p=await find(db,s,'products',id);const qty=integer(item.qty,1,999);const price=p.price;const base=price*qty;const discount=member&&discountRate===20?Math.round(price*.2)*qty:Math.round(base*discountRate/100);const net=base-discount;const tax=Math.round(net*p.tax/100);items.push({productId:id,code:p.code,name:p.name,qty,price,discount,taxRate:p.tax,tax,net,total:net+tax,cost:p.cost,fulfillment:p.stock>=qty?(s.mode==='store'?'stock propio':'stock propio demo'):(s.mode==='store'?'sobre pedido':'sobre pedido demo')});}
 const subtotal=items.reduce((a,i)=>a+i.price*i.qty,0),discount=items.reduce((a,i)=>a+i.discount,0),tax=items.reduce((a,i)=>a+i.tax,0),total=subtotal-discount+tax;integer(total,1,1000000000);
 const d={id:uid(),type:'quote',number:(s.mode==='store'?'COT-':'COT-DEMO-')+uid().slice(0,8).toUpperCase(),status:'borrador',at:now(),client:{id:client.id,name:client.name,segment:client.segment,email:client.email},items,subtotal,discount,tax,total,notes:text(b.notes??'',500,false),...(s.mode==='store'?{memberBenefit:member?'20 % de por vida para usuarios registrados':null,discountRate}:{}),demo:s.mode!=='store'};
 await db.batch([insert(db,s,'documents',d),log(db,s,'cotización creada',d.id)]);return d;
}
async function convert(db,s,b){
 const type=b.type;if(!['order','invoice'].includes(type))fail(400,'Tipo de conversión inválido.');requirePermission(s,type==='order'?'order.write':'invoice.write');await limit(db,s,'documents');const old=await find(db,s,'documents',b.source);
 if(!((old.type==='quote'&&type==='order')||(old.type==='order'&&type==='invoice'))||old.status==='cancelado')fail(409,'Conversión no permitida.');
 const d={...old,id:uid(),source:old.id,type,number:(type==='order'?'PED':'FAC')+(s.mode==='store'?'-':'-DEMO-')+uid().slice(0,8).toUpperCase(),status:type==='order'?'pendiente':'emitido',at:now()};delete d.version;
 if(type==='order'){const results=await db.batch([insert(db,s,'documents',d),log(db,s,'pedido creado',d.id)]);return d;}
 const predicates=old.items.map(()=>"(id=? AND CAST(json_extract(data,'$.stock') AS INTEGER)<?)").join(' OR ');const values=old.items.flatMap(i=>[i.productId,i.qty]);
 const queries=[stmt(db,`INSERT INTO demo_records(workspace,kind,id,data) SELECT ?,?,?,? WHERE (SELECT count(*) FROM demo_records WHERE workspace=? AND kind='products' AND id IN (${old.items.map(()=>'?').join(',')}))=? AND NOT EXISTS(SELECT 1 FROM demo_records WHERE workspace=? AND kind='products' AND (${predicates}))`,s.workspace,'documents',d.id,JSON.stringify(d),s.workspace,...old.items.map(i=>i.productId),old.items.length,s.workspace,...values)];
 for(const i of old.items)queries.push(stmt(db,"UPDATE demo_records SET data=json_set(data,'$.stock',CAST(json_extract(data,'$.stock') AS INTEGER)-?),version=version+1 WHERE workspace=? AND kind='products' AND id=? AND EXISTS(SELECT 1 FROM demo_records WHERE workspace=? AND kind='documents' AND id=?)",i.qty,s.workspace,i.productId,s.workspace,d.id));
 queries.push(stmt(db,"UPDATE demo_records SET data=json_set(data,'$.status','facturado'),version=version+1 WHERE workspace=? AND kind='documents' AND id=? AND EXISTS(SELECT 1 FROM demo_records WHERE workspace=? AND kind='documents' AND id=?)",s.workspace,old.id,s.workspace,d.id));
 queries.push(stmt(db,"INSERT INTO demo_records(workspace,kind,id,data) SELECT ?,?,?,? WHERE EXISTS(SELECT 1 FROM demo_records WHERE workspace=? AND kind='documents' AND id=?)",s.workspace,'audit',uid(),JSON.stringify({event:'documento interno emitido y stock descontado',record:d.id,role:s.role,...(s.mode==='store'?{actor:s.actor}:{}),at:now()}),s.workspace,d.id));
 const result=await db.batch(queries);if(result[0].meta.changes!==1)fail(409,'Stock insuficiente. Registra la recepción del proveedor antes de emitir.');return d;
}
// Customer records are private and persistent, never exposed to public demo roles.
const customerInitialized=new WeakSet();
async function customerSetup(db){if(customerInitialized.has(db))return;await db.batch([
 db.prepare('CREATE TABLE IF NOT EXISTS tr_customers (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, salt TEXT NOT NULL, password TEXT NOT NULL, created TEXT NOT NULL)'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_customer_sessions (token TEXT PRIMARY KEY, customer TEXT NOT NULL REFERENCES tr_customers(id), csrf TEXT NOT NULL, expires INTEGER NOT NULL)'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_vehicles (id TEXT PRIMARY KEY, customer TEXT NOT NULL REFERENCES tr_customers(id), plate TEXT NOT NULL, vin TEXT NOT NULL, chassis TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, data TEXT NOT NULL CHECK(json_valid(data)))'),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS tr_vehicle_vin ON tr_vehicles(customer,vin) WHERE vin!=''"),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS tr_vehicle_plate ON tr_vehicles(customer,plate) WHERE plate!=''"),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS tr_vehicle_chassis ON tr_vehicles(customer,chassis) WHERE chassis!=''")
]);customerInitialized.add(db)}
const customerCookie=(value,age)=>`tr_customer=${value}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=${age}`;
const hex=bytes=>Array.from(new Uint8Array(bytes),v=>v.toString(16).padStart(2,'0')).join('');
async function passwordHash(password,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:100000,hash:'SHA-256'},key,256))}
function sameHash(a,b){let difference=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)difference|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return difference===0}
const customerPassword=value=>{if(typeof value!=='string'||value.length>128||!value.length)fail(400,'Revisa la clave.');return value};
const customerEmail=value=>{const email=text(value,150).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))fail(400,'Revisa tu correo.');return email};
async function customerRate(db,request,action,maximum,window=600000){const key=await digest('customer:'+action+':'+(request.headers.get('CF-Connecting-IP')||'local')+':'+Math.floor(Date.now()/window));await stmt(db,'INSERT INTO demo_login_attempts(key,count,expires) VALUES(?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1',key,Date.now()+window).run();if((await stmt(db,'SELECT count FROM demo_login_attempts WHERE key=?',key).first()).count>maximum)fail(429,'Demasiados intentos. Intenta más tarde.')}
async function customerSession(request,db){const raw=(request.headers.get('Cookie')||'').match(/(?:^|;\s*)tr_customer=([a-zA-Z0-9-]+)/)?.[1];if(!raw)fail(401,'Entra en tu cuenta para guardar y recuperar tus vehículos.');const s=await stmt(db,'SELECT s.*,c.name,c.email FROM tr_customer_sessions s JOIN tr_customers c ON c.id=s.customer WHERE s.token=? AND s.expires>?',await digest(raw),Date.now()).first();if(!s)fail(401,'Tu sesión terminó. Entra de nuevo.');return s}
async function startCustomerSession(db,c){const raw=uid()+uid(),s={token:await digest(raw),customer:c.id,csrf:uid(),expires:Date.now()+86400000};await db.batch([stmt(db,'DELETE FROM tr_customer_sessions WHERE expires<?',Date.now()),stmt(db,'INSERT INTO tr_customer_sessions VALUES(?,?,?,?)',s.token,s.customer,s.csrf,s.expires)]);return json({name:c.name,email:c.email,csrf:s.csrf,expires:s.expires},200,{'Set-Cookie':customerCookie(raw,86400)})}
function validateVehicle(b){const plate=text(b.plate??'',10,false).toUpperCase().replace(/[\s-]/g,''),vin=text(b.vin??'',17,false).toUpperCase(),chassis=text(b.chassis??'',30,false).toUpperCase();if(plate&&!/^[A-Z0-9]{5,10}$/.test(plate))fail(400,'Revisa la placa.');if(vin&&!/^[A-HJ-NPR-Z0-9]{17}$/.test(vin))fail(400,'El VIN debe tener 17 caracteres, sin I, O ni Q.');if(chassis&&!/^[A-Z0-9-]{4,30}$/.test(chassis))fail(400,'Revisa el número de bastidor.');if(!plate&&!vin&&!chassis)fail(400,'Añade la placa, el VIN o el bastidor.');return {plate,vin,chassis,brand:text(b.brand,60),model:text(b.model,100),year:b.year==null||b.year===''?null:integer(b.year,1900,new Date().getUTCFullYear()+1),engine:text(b.engine??'',100,false),color:text(b.color??'',40,false),compatibility:'pending',source:'customer',updated:now()}}
async function customerApi(request,db,path){await customerSetup(db);const method=request.method;
 if(path==='/api/customer/register'&&method==='POST'){await customerRate(db,request,'register',5,3600000);const b=await body(request),email=customerEmail(b.email),name=text(b.name,120),password=customerPassword(b.password);if(password.length<12)fail(400,'Usa una clave de al menos 12 caracteres.');if(b.consent!==true)fail(400,'Autoriza guardar tus datos para crear la cuenta.');const cap=await db.prepare('SELECT count(*) AS n FROM tr_customers').first();if(cap.n>=2000)fail(503,'El registro está temporalmente ocupado.');if(await stmt(db,'SELECT id FROM tr_customers WHERE email=?',email).first())fail(409,'No se pudo crear la cuenta. Prueba entrar o usa otro correo.');const salt=hex(crypto.getRandomValues(new Uint8Array(32))),c={id:uid(),name,email};await stmt(db,'INSERT INTO tr_customers VALUES(?,?,?,?,?,?)',c.id,email,name,salt,await passwordHash(password,salt),now()).run();return startCustomerSession(db,c)}
 if(path==='/api/customer/login'&&method==='POST'){await customerRate(db,request,'login',20);const b=await body(request),email=customerEmail(b.email);await customerRate(db,request,'login-email:'+await digest(email),10);const password=customerPassword(b.password);const c=await stmt(db,'SELECT * FROM tr_customers WHERE email=?',email).first();const candidate=await passwordHash(password,c?.salt||'missing-customer-salt');if(!c||!sameHash(candidate,c.password))fail(401,'Correo o clave incorrectos.');return startCustomerSession(db,c)}
 const s=await customerSession(request,db);if(method!=='GET'&&request.headers.get('X-CSRF-Token')!==s.csrf)fail(403,'Renueva tu sesión antes de guardar.');
 if(path==='/api/customer/me'&&method==='GET')return json({name:s.name,email:s.email,csrf:s.csrf,expires:s.expires});
 if(path==='/api/customer/logout'&&method==='POST'){await stmt(db,'DELETE FROM tr_customer_sessions WHERE token=?',s.token).run();return json({ok:true},200,{'Set-Cookie':customerCookie('',0)})}
 if(path==='/api/customer/vehicles'&&method==='GET'){const {results}=await stmt(db,'SELECT id,version,data FROM tr_vehicles WHERE customer=? ORDER BY rowid DESC LIMIT 30',s.customer).all();return json({vehicles:results.map(r=>({id:r.id,version:r.version,...JSON.parse(r.data)}))})}
 if(path==='/api/customer/vehicles'&&['POST','PATCH'].includes(method)){const b=await body(request),v=validateVehicle(b),data=JSON.stringify(v);
  if(method==='PATCH'){const r=await stmt(db,'UPDATE tr_vehicles SET plate=?,vin=?,chassis=?,data=?,version=version+1 WHERE customer=? AND id=? AND version=?',v.plate,v.vin,v.chassis,data,s.customer,text(b.id,80),integer(b.version,1)).run();if(!r.meta.changes)fail(409,'El vehículo cambió o no está en tu cuenta. Actualiza el garaje.');return json({...v,id:b.id,version:b.version+1})}
  const cap=await stmt(db,'SELECT count(*) AS n FROM tr_vehicles WHERE customer=?',s.customer).first();if(cap.n>=20)fail(409,'Tu garaje admite hasta veinte vehículos.');const id=uid();await stmt(db,'INSERT INTO tr_vehicles(id,customer,plate,vin,chassis,data) VALUES(?,?,?,?,?,?)',id,s.customer,v.plate,v.vin,v.chassis,data).run();return json({...v,id,version:1},201)
 }
 fail(404,'Acción de cuenta no disponible.')
}

async function customerIdentitySetup(db){await db.batch([db.prepare('CREATE TABLE IF NOT EXISTS tr_customer_identity (customer TEXT PRIMARY KEY REFERENCES tr_customers(id),verified INTEGER NOT NULL DEFAULT 0)'),db.prepare('CREATE TABLE IF NOT EXISTS tr_customer_tokens (token TEXT PRIMARY KEY,customer TEXT NOT NULL REFERENCES tr_customers(id),purpose TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0,UNIQUE(customer,purpose))')])}
const mailAvailable=env=>!!env.RESEND_API_KEY&&!!env.EMAIL_FROM;
async function customerMail(db,env,c,purpose){if(!mailAvailable(env))fail(503,'El envío de correos todavía no está activado. Contacta con TOYORENAULT.');const raw=uid()+uid(),hash=await digest(raw),link='https://toyorenault-cjd.pages.dev/cuenta#'+purpose+'/'+raw;await stmt(db,'INSERT INTO tr_customer_tokens VALUES(?,?,?,?,0) ON CONFLICT(customer,purpose) DO UPDATE SET token=excluded.token,expires=excluded.expires,used=0',hash,c.id,purpose,Date.now()+1800000).run();try{const response=await (env.EMAIL_FETCH||fetch)('https://api.resend.com/emails',{method:'POST',signal:AbortSignal.timeout(8000),headers:{Authorization:'Bearer '+env.RESEND_API_KEY,'Content-Type':'application/json'},body:JSON.stringify({from:env.EMAIL_FROM,to:[c.email],subject:purpose==='verify'?'Verifica tu correo · TOYORENAULT':'Recupera tu acceso · TOYORENAULT',text:(purpose==='verify'?'Confirma tu correo.':'Define una nueva frase de acceso.')+'\n'+link+'\nEnlace personal de un solo uso. Vence en 30 minutos. Si no lo solicitaste, ignora este correo.'})});if(!response.ok)throw Error('Mail unavailable');return true}catch{await stmt(db,'DELETE FROM tr_customer_tokens WHERE token=?',hash).run();return false}}
async function customerExtra(request,db,path,env){if(env.STORE_DB)await storeSetup(env);const method=request.method;await customerSetup(db);await customerIdentitySetup(db);
 if(path==='/api/customer/recover'&&method==='POST'){await customerRate(db,request,'recover',5,3600000);const b=await body(request),email=customerEmail(b.email);if(!mailAvailable(env))fail(503,'La recuperación por correo está pendiente de activar el servicio de email.');const c=await stmt(db,'SELECT id,email FROM tr_customers WHERE email=?',email).first();if(c)await customerMail(db,env,c,'reset');return json({message:'Si existe una cuenta con ese correo y el envío está disponible, recibirás un enlace personal.'})}
 if(path==='/api/customer/reset'&&method==='POST'){await customerRate(db,request,'reset',10,3600000);const b=await body(request),token=await digest(text(b.token,150)),t=await stmt(db,"SELECT * FROM tr_customer_tokens WHERE token=? AND purpose='reset' AND used=0 AND expires>?",token,Date.now()).first();if(!t)fail(400,'El enlace no está disponible o venció.');const password=customerPassword(b.password);if(password.length<12)fail(400,'Usa al menos 12 caracteres.');const salt=hex(crypto.getRandomValues(new Uint8Array(32))),hashed=await passwordHash(password,salt);const result=await db.batch([stmt(db,"UPDATE tr_customer_tokens SET used=1 WHERE token=? AND purpose='reset' AND used=0 AND expires>?",token,Date.now()),stmt(db,'UPDATE tr_customers SET salt=?,password=? WHERE id=? AND changes()=1',salt,hashed,t.customer),stmt(db,'DELETE FROM tr_customer_sessions WHERE customer=? AND changes()=1',t.customer)]);if(result[0].meta.changes!==1)fail(409,'El enlace ya se utilizó.');return json({ok:true},200,{'Set-Cookie':customerCookie('',0)})}
 if(path==='/api/customer/confirm-email'&&method==='POST'){await customerRate(db,request,'confirm-email',10,3600000);const b=await body(request),token=await digest(text(b.token,150)),t=await stmt(db,"SELECT * FROM tr_customer_tokens WHERE token=? AND purpose='verify' AND used=0 AND expires>?",token,Date.now()).first();if(!t)fail(400,'El enlace no está disponible o venció.');const result=await db.batch([stmt(db,"UPDATE tr_customer_tokens SET used=1 WHERE token=? AND purpose='verify' AND used=0 AND expires>?",token,Date.now()),stmt(db,'INSERT INTO tr_customer_identity SELECT ?,1 WHERE changes()=1 ON CONFLICT(customer) DO UPDATE SET verified=1',t.customer)]);if(result[0].meta.changes!==1)fail(409,'El enlace ya se utilizó.');return json({ok:true})}
 const s=await customerSession(request,db);if(method!=='GET'&&request.headers.get('X-CSRF-Token')!==s.csrf)fail(403,'Renueva tu sesión antes de guardar.');
 if(path==='/api/customer/settings'&&method==='GET'){const m=await stmt(db,'SELECT verified FROM tr_customer_identity WHERE customer=?',s.customer).first();return json({name:s.name,email:s.email,verified:m?.verified===1,emailService:mailAvailable(env),csrf:s.csrf})}
 if(path==='/api/customer/verify-email'&&method==='POST'){await customerRate(db,request,'verify-email',3,3600000);const sent=await customerMail(db,env,{id:s.customer,email:s.email},'verify');if(!sent)fail(503,'El correo no pudo enviarse. Intenta más tarde.');return json({ok:true})}
 if(path==='/api/customer/export'&&method==='GET'){const {results}=await stmt(db,'SELECT id,version,data FROM tr_vehicles WHERE customer=?',s.customer).all();const c=await stmt(db,'SELECT name,email,created FROM tr_customers WHERE id=?',s.customer).first();return json({format:'toyorenault-garage-v1',at:now(),account:c,vehicles:results.map(r=>({id:r.id,version:r.version,...JSON.parse(r.data)})),requests:env.STORE_DB?(await list(storeDatabase(env),{workspace:storeWorkspace},'requests')).filter(r=>r.customer===s.customer).map(publicPartRequest):[]})}
 if(path==='/api/customer/delete-account'&&method==='POST'){await customerRate(db,request,'delete-account',5,3600000);const b=await body(request),c=await stmt(db,'SELECT salt,password FROM tr_customers WHERE id=?',s.customer).first();if(b.confirm!==true||customerEmail(b.email)!==s.email)fail(400,'Confirma tu correo y la eliminación.');if(!sameHash(await passwordHash(customerPassword(b.password),c.salt),c.password))fail(403,'Revisa tu frase de acceso.');if(env.STORE_DB){await storeSetup(env);await stmt(storeDatabase(env),"DELETE FROM tr_epc_grants WHERE kind='customer' AND subject=?",s.customer).run();await stmt(storeDatabase(env),"DELETE FROM demo_records WHERE workspace=? AND kind='requests' AND json_extract(data,'$.customer')=?",storeWorkspace,s.customer).run()}await db.batch([stmt(db,'DELETE FROM tr_vehicles WHERE customer=?',s.customer),stmt(db,'DELETE FROM tr_customer_tokens WHERE customer=?',s.customer),stmt(db,'DELETE FROM tr_customer_identity WHERE customer=?',s.customer),stmt(db,'DELETE FROM tr_customer_sessions WHERE customer=?',s.customer),stmt(db,'DELETE FROM tr_customers WHERE id=?',s.customer)]);return json({ok:true},200,{'Set-Cookie':customerCookie('',0)})}
 fail(404,'Acción de cuenta no disponible.')
}

async function operations(request,db,s,path,method){
 if(path==='/api/state'&&method==='GET'){
   const visibility={clients:'crm',leads:'crm',products:'stock',offers:'suppliers',documents:'documents',purchases:'purchases',tasks:'tasks',returns:'returns',audit:'audit'};
   const data={};for(const kind of [...kinds,'audit'])data[kind]=hasModule(s,visibility[kind])?await list(db,s,kind):[];
   data.products=data.products.map(p=>visibleProduct(s,p));
   if(s.role==='bodega')data.documents=data.documents.filter(d=>d.type==='order');
   data.documents=data.documents.map(d=>visibleDocument(s,d));
   if(!allowed(s,'cost.read'))data.offers=data.offers.map(({cost,publicPrice,...p})=>s.role==='bodega'?p:{...p,...(publicPrice===undefined?{}:{publicPrice})});
   data.purchases=data.purchases.map(p=>visiblePurchase(s,p));
   if(s.mode==='store')data.requests=hasModule(s,'crm')?await list(db,s,'requests'):[];return json(data);
 }
 if(path==='/api/records'&&method==='POST'){
   const b=await body(request),kind=b.kind;if(!['clients','leads','products','tasks'].includes(kind))fail(400,'Registro inválido.');requirePermission(s,kind==='products'?'catalog.write':kind==='tasks'?'task.write':'crm.write');await limit(db,s,kind);
   const d=validate(kind,b.data||{});if(kind==='products'&&s.mode==='store'){d.published=b.data?.published===true;d.updated=now();}if(kind==='leads')await find(db,s,'clients',d.clientId);await db.batch([insert(db,s,kind,d),log(db,s,kind+' creado',d.id)]);return json(d,201);
 }
 if(path==='/api/records'&&method==='PATCH'){
   const b=await body(request),kind=b.kind;if(!['clients','leads','tasks'].includes(kind))fail(400,'Edición no permitida.');requirePermission(s,kind==='tasks'?'task.write':'crm.write');const old=await find(db,s,kind,b.id);const d=validate(kind,{...old,...b.data});d.id=old.id;d.created=old.created||now();if(kind==='leads')await find(db,s,'clients',d.clientId);return json(await update(db,s,kind,old.id,b.version,d,kind+' actualizado'));
 }
 if(path==='/api/stock'&&method==='POST'){
   requirePermission(s,'stock.write');const b=await body(request),p=await find(db,s,'products',b.id);const delta=integer(b.delta,-99999,99999);if(!delta)fail(400,'Indica una variación de stock.');const reason=text(b.reason,150);const stock=integer(p.stock+delta,0,99999);return json(visibleProduct(s,await update(db,s,'products',p.id,b.version,{...p,stock},'ajuste stock: '+reason)));
 }
 if(path==='/api/quotes'&&method==='POST'){const d=await quote(db,s,await body(request));return json(visibleDocument(s,d),201);}
 if(path==='/api/convert'&&method==='POST'){const d=await convert(db,s,await body(request));return json(visibleDocument(s,d),201);}
 if(path==='/api/purchases'&&method==='POST'){
   requirePermission(s,'purchase.write');await limit(db,s,'purchases');const b=await body(request),p=await find(db,s,'products',b.productId);const offer=await find(db,s,'offers',b.offerId);if(p.code!==offer.code)fail(400,'La oferta no corresponde a la referencia.');const qty=integer(b.qty,1,999);if(offer.stock===null||offer.cost===null)fail(409,'Confirma precio y disponibilidad antes de preparar la compra.');if(qty>offer.stock)fail(409,'Cantidad superior al stock informado; solicita confirmación.');
   const d={id:uid(),number:(s.mode==='store'?'COM-':'COM-DEMO-')+uid().slice(0,8).toUpperCase(),productId:p.id,offerId:offer.id,code:p.code,name:p.name,supplier:offer.supplier,qty,cost:offer.cost,total:offer.cost*qty,status:'borrador',at:now(),demo:s.mode!=='store'};await db.batch([insert(db,s,'purchases',d),log(db,s,s.mode==='store'?'compra preparada; no enviada':'compra demo preparada; no enviada',d.id)]);return json(d,201);
 }
 if(path==='/api/receive'&&method==='POST'){
   requirePermission(s,'receipt.write');const b=await body(request),p=await find(db,s,'purchases',b.id);if(p.status!=='borrador')fail(409,'La compra ya fue recibida.');const product=await find(db,s,'products',p.productId);integer(product.stock+p.qty,0,99999);
   const result=await db.batch([stmt(db,"UPDATE demo_records SET data=json_set(data,'$.status','recibido','$.received',?),version=version+1 WHERE workspace=? AND kind='purchases' AND id=? AND version=? AND json_extract(data,'$.status')='borrador'",now(),s.workspace,p.id,integer(b.version,1)),stmt(db,"UPDATE demo_records SET data=json_set(data,'$.stock',CAST(json_extract(data,'$.stock') AS INTEGER)+?),version=version+1 WHERE workspace=? AND kind='products' AND id=? AND changes()=1",p.qty,s.workspace,product.id),successfulLog(db,s,s.mode==='store'?'recepción de mercancía':'recepción demo',p.id)]);if(result[0].meta.changes!==1)fail(409,'La compra cambió; actualiza el panel.');return json({ok:true});
 }
 if(path==='/api/offers/import'&&method==='POST'){
   requirePermission(s,'offers.write');const b=await body(request);if(!Array.isArray(b.rows)||!b.rows.length||b.rows.length>200)fail(400,'Importa entre 1 y 200 referencias por sesión demo.');await limit(db,s,'offers',201);
   const seen=new Set(),rows=b.rows.map(row=>{const d={id:uid(),supplier:text(row.proveedor,100),code:text(row.referencia,100),name:text(row.nombre,150),brand:text(row.marca,80),stock:row.stock_proveedor===null?null:integer(row.stock_proveedor,0,99999),cost:row.precio_cop===null?null:integer(row.precio_cop),days:row.plazo_dias===null?null:integer(row.plazo_dias,0,365),updated:date(row.actualizado),source:'CSV de prueba',demo:s.mode!=='store'};if(d.updated>now().slice(0,10))fail(400,'Fecha de actualización futura.');const key=d.supplier.toLowerCase()+'|'+d.code.toLowerCase();if(seen.has(key))fail(400,'Referencia duplicada para un proveedor.');seen.add(key);return d;});
   await db.batch([stmt(db,"DELETE FROM demo_records WHERE workspace=? AND kind='offers'",s.workspace),...rows.map(d=>insert(db,s,'offers',d)),log(db,s,'portafolio CSV demo reemplazado',String(rows.length))]);return json({imported:rows.length});
 }
 if(path==='/api/returns'&&method==='POST'){
   requirePermission(s,'return.write');await limit(db,s,'returns');const b=await body(request),invoice=await find(db,s,'documents',b.invoiceId);if(invoice.type!=='invoice')fail(400,'Selecciona un documento interno emitido.');const item=invoice.items.find(i=>i.productId===b.productId);if(!item)fail(400,'Pieza no encontrada en el documento.');const prior=await list(db,s,'returns'),qty=integer(b.qty,1,item.qty);if(prior.filter(r=>r.invoiceId===invoice.id&&r.productId===item.productId).reduce((sum,r)=>sum+r.qty,0)+qty>item.qty)fail(409,'No puedes devolver más unidades de las vendidas.');
   const product=await find(db,s,'products',item.productId);integer(product.stock+qty,0,99999);const d={id:uid(),invoiceId:invoice.id,productId:item.productId,qty,reason:text(b.reason,200),at:now(),status:'registrado',demo:s.mode!=='store'};
   const result=await db.batch([stmt(db,"INSERT INTO demo_records(workspace,kind,id,data) SELECT ?,?,?,? WHERE COALESCE((SELECT sum(CAST(json_extract(data,'$.qty') AS INTEGER)) FROM demo_records WHERE workspace=? AND kind='returns' AND json_extract(data,'$.invoiceId')=? AND json_extract(data,'$.productId')=?),0)+?<=?",s.workspace,'returns',d.id,JSON.stringify(d),s.workspace,invoice.id,item.productId,qty,item.qty),stmt(db,"UPDATE demo_records SET data=json_set(data,'$.stock',CAST(json_extract(data,'$.stock') AS INTEGER)+?),version=version+1 WHERE workspace=? AND kind='products' AND id=? AND changes()=1",qty,s.workspace,item.productId),successfulLog(db,s,'devolución demo registrada; sin nota DIAN',d.id)]);if(result[0].meta.changes!==1)fail(409,'La devolución supera las unidades vendidas.');return json(d,201);
 }
 fail(404,'Acción no disponible.');
}

// Private staff and business records use a separate D1 binding, never the public demo DB.
const storeReady=new WeakSet(),storeWorkspace='toyorenault-store';
function storeDatabase(env){if(!env.STORE_DB)fail(503,'Conecta la base privada STORE_DB para activar el almacén.');if(env.STORE_DB===env.DB)fail(503,'La base privada debe ser distinta de la demostración.');return {prepare:sql=>env.STORE_DB.prepare(sql.replaceAll('demo_records','tr_store_records').replaceAll('demo_login_attempts','tr_auth_attempts')),batch:q=>env.STORE_DB.batch(q)}}
async function storeSetup(env){const raw=env.STORE_DB;if(storeReady.has(raw))return;const db=storeDatabase(env);await db.batch([
 db.prepare('CREATE TABLE IF NOT EXISTS tr_store_meta (key TEXT PRIMARY KEY,value TEXT NOT NULL)'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_staff (id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,salt TEXT NOT NULL,password TEXT NOT NULL,created TEXT NOT NULL)'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_staff_sessions (token TEXT PRIMARY KEY,staff TEXT NOT NULL REFERENCES tr_staff(id),csrf TEXT NOT NULL,expires INTEGER NOT NULL)'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_staff_invites (token TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,role TEXT NOT NULL,purpose TEXT NOT NULL,expires INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0)'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_epc_grants (kind TEXT NOT NULL,subject TEXT NOT NULL,email TEXT NOT NULL,enabled INTEGER NOT NULL,PRIMARY KEY(kind,subject))'),
 db.prepare('CREATE TABLE IF NOT EXISTS tr_auth_attempts (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL)'),
 db.prepare("CREATE TABLE IF NOT EXISTS tr_store_records (workspace TEXT NOT NULL,kind TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,data TEXT NOT NULL CHECK(json_valid(data)) CHECK(kind!='products' OR CAST(json_extract(data,'$.stock') AS INTEGER) BETWEEN 0 AND 99999),PRIMARY KEY(workspace,kind,id))"),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS tr_store_conversion_once ON tr_store_records(workspace,json_extract(data,'$.source'),json_extract(data,'$.type')) WHERE kind='documents' AND json_extract(data,'$.source') IS NOT NULL"),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS tr_store_sku ON tr_store_records(workspace,lower(json_extract(data,'$.code'))) WHERE kind='products'"),
 db.prepare("CREATE UNIQUE INDEX IF NOT EXISTS tr_store_offer ON tr_store_records(workspace,lower(json_extract(data,'$.supplier')),lower(json_extract(data,'$.code'))) WHERE kind='offers'")
]);storeReady.add(raw)}
